import { Component, OnDestroy, OnInit } from '@angular/core';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs';
import { CommonModule } from '@angular/common';
import { Dispositivos } from '../../enums/dispositivos.enum';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { MyTitleComponent } from '../diversos/my-title/my-title.component';
import { environment } from '../../../environments/environment';
import { DiversosService } from '../../services/diversos.service';

@Component({
  selector: 'calculadora-offline',
  templateUrl: './calculadora-offline.component.html',
  styleUrl: './calculadora-offline.component.scss',
  standalone: true,
  imports: [
    CommonModule,
    MyTitleComponent,
    RouterModule,
  ],
})
export class CalculadoraOfflineComponent implements OnInit, OnDestroy {

  private readonly subscriptions: Subscription = new Subscription();

  dispositivo: string = '';

  sistema: string = 'Windows';

  constructor(
    private readonly dispositivoService: DispositivoService,
    private readonly router: Router,
    public activatedRoute: ActivatedRoute,
    private diversosService: DiversosService
  ) { }

  ngOnInit(): void {
    this.sistema = this.detectarSistemaOperacional();
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  irPara(url: string) {
    this.router.navigate([url]);
  }

  voltar() {
    this.router.navigate(['/calculadora']);
  }

  obterUrl(platform: string) {
    this.diversosService.obterUrl(platform).subscribe({
      next: (response) => {
        if (response && response.downloadUrl) {
          window.open(response.downloadUrl, '_blank');
        } else {
          console.error('URL não encontrada na resposta:', response);
        }
      },
      error: (error) => {
        console.error('Erro ao obter URL:', error);
      }
    });
  }

  verificarDispositivo(dispositivo: string) {
    this.dispositivo = dispositivo;
    switch (dispositivo) {
      case Dispositivos.XSMALL:
        break;
      case Dispositivos.SMALL:
        break;
      case Dispositivos.MEDIUM:
        break;
      case Dispositivos.LARGE:
        break;
      case Dispositivos.XLARGE:
        break;
      default:
        break;
    }
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo) => {
        this.dispositivo = dispositivo;
        this.verificarDispositivo(dispositivo);
      })
    );
  }

  detectarSistemaOperacional(): string {
    const userAgent = navigator.userAgent;
    
    if (userAgent.includes('Windows NT')) {
      return 'Windows';
    } else if (userAgent.includes('Mac OS X') || userAgent.includes('Macintosh')) {
      return 'macOS';
    } else if (userAgent.includes('Linux')) {
      return 'Linux';
    } //else if (userAgent.includes('Android')) {
      //return 'Android';
    //} //else if (userAgent.includes('iPhone') || userAgent.includes('iPad')) {
      //return 'iOS';
    //}
    else {
      return 'Windows';
    }
  }

}
